with incoming(lemma, kind, sense_id, ordinal, pos, gender, text, example, example_translation) as (values ('ændre kurs', 'phrase', '48778e84-e7f1-5029-8737-dd58a87ad3bf', 1, 'verb', null, 'to change course', 'Skibet ændrede kurs for at undgå stormen.', 'The ship changed course to avoid the storm.'), ('elske med', 'phrase', 'f658a3df-5554-5ee2-945f-78b1de15cbc1', 1, 'verb', null, 'to make love', 'De elskede med hinanden hele natten.', 'They made love to each other all night.'), ('brede sig', 'phrase', '88f17d8c-9b5a-59ac-a6dd-65badb00cdc5', 1, 'verb', null, 'to spread', 'Nyheden bredte sig hurtigt i byen.', 'The news spread quickly in the city.'), ('brede sig', 'phrase', '9ac47aac-4379-5467-9ec6-dcfd4984a030', 2, 'verb', null, 'to stretch out (of a landscape)', 'Sletten breder sig foran os.', 'The plain spreads out in front of us.'), ('komme i tanke om', 'phrase', '5999d985-92db-525f-8b72-9a7e9b5ff768', 1, 'verb', null, 'to remember (suddenly)', 'Jeg kom i tanke om, at jeg havde glemt mine nøgler.', 'I remembered that I had forgotten my keys.'), ('komme i tanker om', 'phrase', '74b19243-d89d-528f-9cfb-15ef81e76c8d', 1, 'verb', null, 'to remember (suddenly)', 'Jeg kom i tanker om, at jeg havde glemt min nøgle.', 'I remembered that I had forgotten my key.'), ('være forkert på den', 'phrase', '9db81698-d278-5449-acb4-5156b5b3a770', 1, 'verb', null, 'to be mistaken', 'Du er forkert på den, hvis du tror, jeg kommer i morgen.', 'You''re wrong if you think I''ll come tomorrow.'), ('ringe sammen', 'phrase', '9edff16d-5c03-5a8b-be7a-e3f3f799ec17', 1, 'verb', null, 'to call each other', 'Vi ringer sammen hver aften inden sengetid.', 'We call each other every evening before bedtime.'), ('skære ned', 'phrase', '667973c5-7042-564a-8023-0006252c9a1a', 1, 'verb', null, 'to cut back (expenses, staff)', 'Virksomheden skar ned på udgifterne sidste år.', 'The company cut back on expenses last year.'), ('blive mand og kone', 'phrase', 'e033dd7a-07c1-597d-b0ea-9331f0748d43', 1, 'verb', null, 'to get married (become husband and wife)', 'De blev mand og kone i en lille kirke sidste sommer.', 'They became husband and wife in a small church last summer.'), ('der er pres på', 'phrase', 'c2c2eb9b-c976-5b4f-bd7a-37efa4c0c4b9', 1, 'phrase', null, 'there is pressure, things are hectic', 'Der er pres på i køkkenet lige før gæsterne kommer.', 'There is pressure in the kitchen just before the guests arrive.'), ('gøre tegn', 'phrase', 'c5e3de84-4eee-556e-a501-b649133f1d86', 1, 'verb', null, 'to signal', 'Hun gjorde tegn til tjeneren, at hun ville betale.', 'She motioned to the waiter that she would pay.'), ('gøre tegn til', 'phrase', '057264db-09c4-5a84-9d6b-d5e4f2f24279', 1, 'verb', null, 'to make a sign (to do something)', 'Han gjorde tegn til, at vi skulle følge med.', 'He motioned for us to follow.'), ('tegne til', 'phrase', '5e638664-986b-507c-9a7c-b6d37049d2b2', 1, 'verb', null, 'to look (seem)', 'Det tegner til at blive en god dag.', 'It promises to be a good day.'), ('holde sig varm', 'phrase', '14df8ba7-96dc-569c-b425-791d7aa977fb', 1, 'verb', null, 'to keep warm', 'Jeg tager en ekstra trøje på for at holde mig varm.', 'I put on an extra sweater to keep warm.'), ('gå til angreb', 'phrase', 'ed3c37a4-c078-5f62-8a41-655b03cabb22', 1, 'verb', null, 'to attack (launch an attack)', 'Soldaterne gik til angreb ved daggry.', 'The soldiers attacked at dawn.'), ('være galt på den', 'phrase', '3fe1ea1c-8742-5626-90c1-d295f60f2733', 1, 'verb', null, 'to be mistaken, to be wrong', 'Jeg tror, du er galt på den med den information.', 'I think you''re wrong about that information.'), ('tale forbi hinanden', 'phrase', '77537748-abb6-5a4f-8faa-6ce33aed3c74', 1, 'verb', null, 'to talk past each other', 'Vi talte forbi hinanden hele aftenen og blev uvenner.', 'We talked past each other all evening and fell out.'), ('gribe ind', 'phrase', '9e2b776e-5a3a-590e-9ea7-c1b15aef74e5', 1, 'verb', null, 'to intervene', 'Politiet måtte gribe ind, da demonstrationen blev voldelig.', 'The police had to intervene when the demonstration turned violent.'), ('få styr på', 'phrase', 'eae2c396-c9a0-58ab-8ed4-29e5badf9b90', 1, 'verb', null, 'to get a handle on (organise)', 'Hun fik styr på sine papirer inden mødet.', 'She got her papers in order before the meeting.'), ('være i bevægelse', 'phrase', 'bcd2194d-ad36-54af-90f3-6bb97b5a7bc3', 1, 'verb', null, 'to be moving', 'Bilen er i bevægelse, selv om den kører langsomt.', 'The car is moving, even though it is moving slowly.'), ('gøre opmærksom på', 'phrase', '98b60b3e-db37-5d21-8a45-588d18034b3c', 1, 'verb', null, 'to draw attention (to something)', 'Læreren gjorde opmærksom på fejlen i teksten.', 'The teacher pointed out the error in the text.'), ('stå ansigt til ansigt', 'phrase', '9e9cc310-5e7c-563a-9c72-a3122a8c1cbe', 1, 'verb', null, 'to stand face to face', 'De stod ansigt til ansigt i den lille elevator.', 'They stood face to face in the small elevator.'), ('kunne bunde', 'phrase', '0ec53350-f771-5c44-9f6a-ba3f6e49fbc7', 1, 'verb', null, 'to be able to touch the bottom (in water)', 'Han kan bunde i den lave ende af poolen.', 'He can touch the bottom in the shallow end of the pool.'), ('gifte sig ind i', 'phrase', 'd0964726-5094-5360-b20c-8db51c23202f', 1, 'verb', null, 'to marry into (a family)', 'Han giftede sig ind i en rig familie.', 'He married into a wealthy family.'), ('skaffe sig af med', 'phrase', '95e5ddb1-5d10-568f-85e0-26d07db34358', 1, 'verb', null, 'to get rid of', 'Hun vil gerne skaffe sig af med sin gamle cykel.', 'She wants to get rid of her old bike.'), ('sidde oppe', 'phrase', '4e204935-bca4-59c8-b5f7-15caac9ffad3', 1, 'verb', null, 'to stay up', 'Børnene sad oppe til midnat i går.', 'The children stayed up until midnight yesterday.'), ('første skridt', 'phrase', 'd0bbdf7b-7291-501d-b785-c4bef37fdb12', 1, 'phrase', null, 'first step (in a process)', 'At spare penge er det første skridt mod en bedre økonomi.', 'Saving money is the first step towards a better economy.'), ('have fat i', 'phrase', '04ac4a3e-8c42-58e7-8c4c-4ec0de3a05fb', 1, 'verb', null, 'to hold, to grab', 'Jeg har fat i din taske.', 'I am holding your bag.'), ('flyve ind', 'phrase', '17745ce7-6f3d-5d3b-9c8b-a68759d43a4f', 1, 'verb', null, 'to fly in (enter flying)', 'Fuglen fløj ind ad vinduet.', 'The bird flew in through the window.'), ('løbe med snak', 'phrase', '7550700e-600c-59ac-a99b-40dfeee3a1fa', 1, 'verb', null, 'to get carried away talking (and lose track of time)', 'Vi løb med snak og glemte helt aftensmaden.', 'We got carried away talking and completely forgot about dinner.'), ('føre en samtale', 'phrase', '45d024c5-d299-5088-aa37-7c403126ec85', 1, 'verb', null, 'to have a conversation', 'De fører en samtale om vejret.', 'They have a conversation about the weather.'), ('tage tøj på', 'phrase', '0cdb9233-eed1-5bd4-8c78-c95c29cd278e', 1, 'verb', null, 'to get dressed', 'Jeg tager tøj på, inden jeg går ud.', 'I get dressed before I go out.'), ('investere i', 'phrase', '6a76f49c-00f6-537d-99c7-2aed9404a89d', 1, 'verb', null, 'to invest (money) in', 'Mange vælger at investere i aktier.', 'Many people choose to invest in stocks.'), ('drikke op', 'phrase', '34c3f377-4343-5569-8222-fd0ab0d8341e', 1, 'verb', null, 'to finish a drink', 'Han drak op og gik hjem.', 'He drank up and went home.'), ('drikke sig fuld', 'phrase', 'b47cefa0-c328-52b2-95c1-352696ea7b9a', 1, 'verb', null, 'to get drunk', 'Han drikker sig fuld hver fredag.', 'He gets drunk every Friday.'), ('drikke tæt', 'phrase', 'ec4dc882-6fd8-5cfc-93fb-3f716597ccdf', 1, 'verb', null, 'to drink heavily', 'Han drak tæt hele weekenden.', 'He drank heavily all weekend.'), ('brænde sig på', 'phrase', '5e1be1ab-76a3-56d8-9a4e-f67f9239a6ee', 1, 'verb', null, 'to burn oneself', 'Pas på du ikke brænder dig på den varme pande.', 'Be careful not to burn yourself on the hot pan.'), ('brænde sig på', 'phrase', '129ed172-dab3-53db-8c0f-4151d2121cf0', 2, 'verb', null, 'to get burned (suffer bad consequences)', 'Mange investorer brændte sig på aktiemarkedet sidste år.', 'Many investors got burned on the stock market last year.'), ('brænde ud', 'phrase', 'e479c414-76b1-5cb9-b84d-44751d48355f', 1, 'verb', null, 'to burn out (emotionally)', 'Jeg brænder ud, hvis jeg arbejder for meget.', 'I burn out if I work too much.'), ('tyde på', 'phrase', 'c341b3d2-946e-590d-bfb0-be1e35b67665', 1, 'verb', null, 'to indicate (something)', 'De mørke skyer tyder på regn.', 'The dark clouds indicate rain.'), ('løfte op i', 'phrase', '5ac1a4c1-c959-50df-ad8a-52790c2bd7f1', 1, 'verb', null, 'to lift (sth.) slightly', 'Hun løftede op i låget for at kigge ned i gryden.', 'She lifted the lid slightly to look into the pot.'), ('løfte sig', 'phrase', '64b7c721-25aa-54d2-bf2d-bb8735b2759d', 1, 'verb', null, 'to lift, to rise (of fog, curtain)', 'Tågen løftede sig langsomt over marken.', 'The fog slowly lifted over the field.'), ('meddele sig', 'phrase', '98996bd4-686b-5683-b2c4-ad52c37c6951', 1, 'verb', null, 'to manifest itself, to make itself felt (of a feeling, pain)', 'Trætheden begyndte at meddele sig efter den lange gåtur.', 'The fatigue began to manifest itself after the long walk.'), ('være undervejs', 'phrase', '0904a524-8bf9-50d3-a56f-21b863256db4', 1, 'verb', null, 'to be on the way', 'Pakken er undervejs og kommer i morgen.', 'The package is on its way and will arrive tomorrow.')),
known as (
  select incoming.* from incoming
  where exists (
    select 1 from public.word_catalog_sense existing
    where existing.lemma = incoming.lemma and existing.kind = incoming.kind
      and existing.sense_id = incoming.sense_id::uuid and existing.lang <> 'en'
  )
),
written as (
  insert into public.word_catalog_sense (lemma, kind, sense_id, ordinal, lang, text, pos, gender, example, example_translation, generator)
  select lemma, kind, sense_id::uuid, ordinal, 'en', text, pos, gender, example, example_translation, 'pipeline-phrases-0014' from known
  on conflict (lemma, kind, sense_id, lang) do update set
    text = excluded.text, example = excluded.example, example_translation = excluded.example_translation, generator = excluded.generator
  returning 1
)
select (select count(*) from incoming) as incoming, (select count(*) from known) as matched, (select count(*) from written) as written;
